PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS patients (id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, birth_date TEXT, age INTEGER, sex TEXT, marital_status TEXT, profession TEXT, nationality TEXT, address TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS anamneses (id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, main_complaint TEXT, hda TEXT, surgery_history TEXT, family_history TEXT, smoking TEXT, alcohol TEXT, physical_activity TEXT, illicit_drugs TEXT, diabetes INTEGER DEFAULT 0, hypertension INTEGER DEFAULT 0, heart_disease INTEGER DEFAULT 0, allergies TEXT, continuous_medications TEXT, laboratory_exams TEXT, blood_pressure TEXT, heart_rate TEXT, respiratory_rate TEXT, temperature TEXT, spo2 TEXT, capillary_glucose TEXT, oxygen_saturation TEXT, pain_scale TEXT, diagnosis TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evolutions (id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, entry_date TEXT, entry_time TEXT, sector TEXT, consciousness TEXT, locomotion TEXT, emotional_condition TEXT, companion TEXT, companion_name TEXT, hygiene_body INTEGER DEFAULT 0, hygiene_oral INTEGER DEFAULT 0, hygiene_intimate INTEGER DEFAULT 0, diet_type TEXT, diet_restriction TEXT, diuresis TEXT, evacuation TEXT, physiological_observations TEXT, puncture_date TEXT, medication_information TEXT, allergy_information TEXT, general_observation TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
